const inputData = $input.first().json || {};
const body = inputData.body || inputData;

const email = (body.email || body.user?.email || 'admin@sonar.com').trim().toLowerCase();
const username = body.username || body.user?.name || body.userName || 'Usuario Sonar';
const reviewId = body.reviewId || body.id || 'N/A';
const content = body.content || body.message || 'Sin texto de comentario';
const reason = body.reason || 'Lenguaje o contenido subido de tono detectado por IA';
const timestamp = body.timestamp || new Date().toISOString();

const promptText = `Evalúa y redacta una advertencia formal para el usuario ${username} sobre el comentario: "${content}". El motivo detectado es: ${reason}.`;

return [{
  json: {
    email,
    username,
    reviewId,
    content,
    reason,
    promptText,
    timestamp,
    subject: `⚠️ Aviso de Seguridad y Moderación en SONAR - Cuenta en revisión`
  }
}];

const response = $input.first().json;
let analysisText = '';

try {
  if (response.output) {
    analysisText = response.output;
  } else if (response.text) {
    analysisText = response.text;
  } else {
    analysisText = typeof response === 'string' ? response : JSON.stringify(response);
  }
} catch (err) {
  analysisText = 'Análisis de moderación completado por IA.';
}

return [{
  json: {
    success: true,
    aiFlagged: true,
    message: 'Reseña procesada por IA y enviada a moderación del administrador.',
    analysis: analysisText,
    timestamp: new Date().toISOString()
  }
}];
